114→// ReadSession reads a session from Factory AI Droid's storage (JSONL transcript file).
115→// The session data is stored in NativeData as raw JSONL bytes.
116→// ModifiedFiles is computed by parsing the transcript.
117→func (f *FactoryAIDroidAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
118→	if input.SessionRef == "" {
119→		return nil, errors.New("session reference (transcript path) is required")
120→	}
121→
122→	data, err := os.ReadFile(input.SessionRef)
123→	if err != nil {
124→		return nil, fmt.Errorf("failed to read transcript: %w", err)
125→	}
126→
127→	lines, _, err := ParseDroidTranscriptFromBytes(data, 0)
128→	if err != nil {
129→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
130→	}
131→
132→	return &agent.AgentSession{
133→		SessionID:     input.SessionID,
134→		AgentName:     f.Name(),
135→		SessionRef:    input.SessionRef,
136→		StartTime:     time.Now(),
137→		NativeData:    data,
138→		ModifiedFiles: ExtractModifiedFiles(lines),
139→	}, nil
140→}
