142→// WriteSession writes a session to Factory AI Droid's storage (JSONL transcript file).
143→// Uses the NativeData field which contains raw JSONL bytes.
144→func (f *FactoryAIDroidAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
145→	if session == nil {
146→		return errors.New("session is nil")
147→	}
148→
149→	if session.AgentName != "" && session.AgentName != f.Name() {
150→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, f.Name())
151→	}
152→
153→	if session.SessionRef == "" {
154→		return errors.New("session reference (transcript path) is required")
155→	}
156→
157→	if len(session.NativeData) == 0 {
158→		return errors.New("session has no native data to write")
159→	}
160→
161→	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
162→		return fmt.Errorf("failed to create session directory: %w", err)
163→	}
164→
165→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
166→		return fmt.Errorf("failed to write transcript: %w", err)
167→	}
168→
169→	return nil
170→}
