329→// droidMessage builds a Droid JSONL "message" line with the given id, role, and optional usage.
330→func droidMessage(t *testing.T, id, role string, usage map[string]int) string {
331→	t.Helper()
332→	inner := map[string]interface{}{
333→		"role":    role,
334→		"content": []interface{}{},
335→	}
336→	if usage != nil {
337→		inner["id"] = id
338→		inner["usage"] = usage
339→	}
340→	msg, err := json.Marshal(inner)
341→	if err != nil {
342→		t.Fatalf("failed to marshal inner message: %v", err)
343→	}
344→	line := map[string]interface{}{
345→		"type":    "message",
346→		"id":      id,
347→		"message": json.RawMessage(msg),
348→	}
349→	b, err := json.Marshal(line)
350→	if err != nil {
351→		t.Fatalf("failed to marshal droid line: %v", err)
352→	}
353→	return string(b)
354→}
