361→	// Line 1: user message (no tokens)
362→	// Line 2: assistant message with 10 input, 20 output tokens
363→	// Line 3: session_event (non-message)
364→	// Line 4: assistant message with 5 input, 30 output tokens
365→	transcript := "" +
366→		`{"type":"session_start","id":"s1"}` + "\n" +
367→		droidMessage(t, "m1", "user", nil) + "\n" +
